export enum View {
  LOGIN = 'LOGIN',
  HOME = 'HOME',
  PIX = 'PIX',
  EXTRATO = 'EXTRATO',
  PLANEJAR = 'PLANEJAR',
  SHOPPING = 'SHOPPING',
  CARTAO = 'CARTAO'
}

export interface Transaction {
  id: string;
  type: 'pix_enviado' | 'pix_recebido' | 'compra' | 'recompensa' | 'estorno';
  title: string;
  description: string;
  amount: number;
  date: string;
  time: string;
  isNegative: boolean;
  cancelled?: boolean;
}

export interface PlayerData {
  nick: string;
  uuid: string;
  balance: number;
  creditLimit: number;
  currentInvoice: number;
}

import React, { useState } from 'react';
import { View, PlayerData } from './types';
import LoginView from './components/LoginView';
import HomeView from './components/HomeView';
import PixArea from './components/PixArea';
import StatementArea from './components/StatementArea';
import BottomNav from './components/BottomNav';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.LOGIN);
  const [user, setUser] = useState<PlayerData | null>(null);
  const [isBalanceVisible, setIsBalanceVisible] = useState(true);

  const handleLoginSuccess = (playerData: PlayerData) => {
    setUser(playerData);
    setCurrentView(View.HOME);
  };

  const renderView = () => {
    if (!user || currentView === View.LOGIN) {
      return <LoginView onLoginSuccess={handleLoginSuccess} />;
    }

    switch (currentView) {
      case View.PIX:
        return <PixArea onBack={() => setCurrentView(View.HOME)} player={user} />;
